// Package profiles holds the built-in browser profiles, one embedded JSON
// file per browser version and platform, taken from captures of the real
// browser. Every accessor returns a fresh copy. Chrome, Firefox and Safari
// track each browser's newest version on macOS; an accessor named for the
// browser and another platform, such as ChromeWindows, tracks the newest on
// that platform and exists once that platform has a profile (decision
// 0047). Versioned accessors (Chrome156MacOS) stay fixed. The accessors are
// generated by cmd/profilegen (go generate ./profiles).
package profiles

import (
	"embed"
	"fmt"
	"reflect"
	"slices"
	"sync"

	"github.com/roachadam/mimicry/profile"
)

//go:generate go run ../cmd/profilegen

//go:embed data/*.json
var data embed.FS

// decoded holds each built-in profile, parsed and validated on first use.
// The accessors hand out deep copies of it, never it.
var decoded = func() map[string]func() (*profile.Profile, error) {
	m := make(map[string]func() (*profile.Profile, error), len(names))
	for _, name := range names {
		m[name] = sync.OnceValues(func() (*profile.Profile, error) {
			b, err := data.ReadFile("data/" + name + ".json")
			if err != nil {
				return nil, err
			}

			return profile.Parse(b)
		})
	}

	return m
}()

// load returns a copy of an embedded profile. Every embedded file is
// validated by the generator and by this package's tests, so a failure here
// is a build defect.
func load(name string) *profile.Profile {
	p, err := ByName(name)
	if err != nil {
		panic(err)
	}

	return p
}

// ByName returns a fresh copy of the built-in profile called name, for example
// "chrome-155-macos".
func ByName(name string) (*profile.Profile, error) {
	get, ok := decoded[name]
	if !ok {
		return nil, fmt.Errorf("profiles: %q is not a built-in profile", name)
	}

	p, err := get()
	if err != nil {
		return nil, err
	}

	var c profile.Profile

	deepCopy(reflect.ValueOf(&c).Elem(), reflect.ValueOf(p).Elem())

	return &c, nil
}

// deepCopy copies src into dst, which is its type's zero value, sharing
// nothing a caller can change: every pointer, slice and map is new; strings,
// which are immutable, are shared. A profile holds no interfaces, channels
// or functions. A value with no pointer, slice or map in it (a header's
// name and value) is copied whole rather than field by field.
func deepCopy(dst, src reflect.Value) {
	if plain(src.Type()) {
		dst.Set(src)

		return
	}

	switch src.Kind() {
	case reflect.Pointer:
		if !src.IsNil() {
			n := reflect.New(src.Type().Elem())
			deepCopy(n.Elem(), src.Elem())
			dst.Set(n)
		}

	case reflect.Slice:
		if !src.IsNil() {
			n := reflect.MakeSlice(src.Type(), src.Len(), src.Len())
			if plain(src.Type().Elem()) {
				reflect.Copy(n, src)
			} else {
				for i := range src.Len() {
					deepCopy(n.Index(i), src.Index(i))
				}
			}

			dst.Set(n)
		}

	case reflect.Array:
		for i := range src.Len() {
			deepCopy(dst.Index(i), src.Index(i))
		}

	case reflect.Map:
		if !src.IsNil() {
			n := reflect.MakeMapWithSize(src.Type(), src.Len())
			for it := src.MapRange(); it.Next(); {
				v := reflect.New(src.Type().Elem()).Elem()
				deepCopy(v, it.Value())
				n.SetMapIndex(it.Key(), v)
			}

			dst.Set(n)
		}

	case reflect.Struct:
		for i := range src.NumField() {
			deepCopy(dst.Field(i), src.Field(i))
		}

	default:
		panic("profiles: a profile holds a " + src.Kind().String())
	}
}

// plains caches plain by type.
var plains sync.Map // reflect.Type → bool

// plain says whether a value of type t holds no pointer, slice, map,
// interface, channel or function, so that assigning it copies all of it.
// Strings count as plain: they are immutable.
func plain(t reflect.Type) bool {
	if v, ok := plains.Load(t); ok {
		p, _ := v.(bool)

		return p
	}

	var p bool

	switch t.Kind() {
	case reflect.Array:
		p = plain(t.Elem())
	case reflect.Struct:
		p = true
		for f := range t.Fields() {
			p = p && plain(f.Type)
		}

	case reflect.Pointer, reflect.Slice, reflect.Map,
		reflect.Interface, reflect.Chan, reflect.Func, reflect.UnsafePointer:
		p = false
	default:
		p = true
	}

	plains.Store(t, p)

	return p
}

// Names lists every built-in profile, deprecated ones included.
func Names() []string {
	return slices.Clone(names)
}

// Supported lists the built-in profiles that are not deprecated: the newest
// five versions of each browser on each platform (decision 0035).
func Supported() []string {
	return slices.Clone(supported)
}
